import{_ as r,h as i,i as a,c as n,v as t,p as d,x as l,m,e as h,S as s}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"Decode 的显存墙","description":"","frontmatter":{"title":"Decode 的显存墙","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/decode-memory-wall.md","filePath":"llm/decode-memory-wall.md","lastUpdated":1788454257000}'),c={name:"llm/decode-memory-wall.md"};function p(E,e,A,B,_,f){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="decode-的显存墙" tabindex="-1">Decode 的显存墙 <a class="header-anchor" href="#decode-的显存墙" aria-label="Permalink to &quot;Decode 的显存墙&quot;">​</a></h1><div class="epigraph"><p>逐步生成时每一步的查询长度是 1，算术强度掉到带宽屋顶之下：墙钟由读出权重与不断变长的 KV 决定，而不是由峰值 FLOPS 决定。</p><footer>—— 把屋顶线模型接到自回归解码：compute-bound 的是 prefill，memory/bandwidth-bound 的是 decode</footer></div><p>Decode 每步只为最新 token 做一次前向：读全部层的权重，读该请求截至目前的 KV，写回一行新的键值，发出一个 logits。与<a href="/llm/prefill-compute">Prefill</a> 相反，权重无法被长序列摊销，KV 还随已生成长度 \\(n\\) 线性膨胀。现代 GPU 的 Tensor Core 峰值远高于把这些字节从 HBM 搬到片上的能力，于是出现 <strong>显存墙</strong>：加更多 FLOPS 几乎不降 TPOT，加带宽、减字节、加大 batch 里的复用才降。本篇把这堵墙写成不等式与屋顶线，压缩手段见 <a href="/llm/kv-as-long-context">KV 预算</a> 与 <a href="/llm/gqa">GQA</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一步 decode 的主导流量大约是：参数字节（若权重不驻 L2）加上</p> \\[\\mathrm{KV\\ bytes}\\propto L\\cdot n\\cdot h_{\\mathrm{kv}}\\cdot d\\cdot 2\\cdot b, \\]<p>\\(L\\) 层数，\\(n\\) 当前上下文，\\(b\\) 元素宽度。算术量则是对 \\(n\\) 个键的点积加 FFN 的一次「瘦」GEMM（激活行数为 1 或小 batch）。算术强度随 \\(n\\) 上升（注意力部分），但权重项仍是每步扫一遍巨量参数——除非 batch 大到同一份权重服务许多请求。小 batch、长上下文的聊天，正好落在强度最低的角落：既要扫权重，又要扫很长的 KV。</p><p>产品表现是：GPU 利用率仪表显示很低，但延迟已经顶满；换一张算力翻倍、带宽差不多的卡，吐词速度几乎不动。这不是实现没写好，是工作点在带宽屋顶下。R1 类长思维链把 \\(n\\) 再乘一截，墙从「并发稍高就 OOM」变成「单请求也搬不动」。</p><h3 id="两堵墙-容量与带宽" tabindex="-1">两堵墙：容量与带宽 <a class="header-anchor" href="#两堵墙-容量与带宽" aria-label="Permalink to &quot;两堵墙：容量与带宽&quot;">​</a></h3><p>容量墙：KV 与权重之和超过 HBM，请求进不去或被换出。带宽墙：放得下，但每步要搬的字节 / \\(B_{\\mathrm{HBM}}\\) 大于核计算时间。量化、<a href="/llm/mla">MLA</a>、驱逐解决容量，也降低带宽压力；它们对 prefill 的 TTFT 帮助是另一张表。只报「能跑 128K」而 TPOT 从 20ms 变成 200ms，用户感受到的仍是墙。</p><p><span class="marginnote">查询头数不进 KV 字节公式。GQA 减的是 \\(h_{\\mathrm{kv}}\\)。把 MHA 的头数代入 decode 流量，会把带宽需求高估 \\(h_q/h_{\\mathrm{kv}}\\) 倍，规划出来的卡型是错的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先把一步时间估成</p> \\[T_{\\mathrm{step}} \\;\\gtrsim\\; \\frac{W_{\\mathrm{bytes}}+K_{\\mathrm{bytes}}(n)}{\\eta_b\\,B_{\\mathrm{HBM}}} \\]<p>再与计算时间 \\(\\mathrm{FLOPs}/(\\eta_c\\,\\mathrm{peak})\\) 取大者。decode 上前者几乎总更大。优化按分子、分母分类：</p><ul><li>减 \\(W_{\\mathrm{bytes}}\\)：权重量化、MoE 只加载被点到的专家（命中率低时反而更疼）。</li><li>减 \\(K_{\\mathrm{bytes}}\\)：GQA/MQA/MLA、KV 量化、滑窗、驱逐、更短的思维链策略。</li><li>增复用：连续批处理让同一份权重乘在许多序列上，强度随 batch 升，工作点向计算屋顶挪——这是 vLLM 一类系统用分页 KV 换高并发的原因之一。</li><li>增 \\(B_{\\mathrm{HBM}}\\)：换 HBM 规格，比换 FLOPS 更对症。</li></ul><p>推测解码用草稿模型多吐几个 token 再验证，企图用额外计算换更少的逐步权重扫描；它只有在验证接受率高、且主模型仍受带宽限制时才划算。接受率低就变成更贵的 prefill 式核。</p>',17)),(a(),d(s,null,{default:l(()=>[h(o,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E4%B8%80%E6%AD%A5%20decode%22%5D%20--%3E%20W%5B%22%E8%AF%BB%E6%9D%83%E9%87%8D%20W%22%5D%0A%20%20STEP%20--%3E%20K%5B%22%E8%AF%BB%20KV(n)%22%5D%0A%20%20W%20--%3E%20ROOF%7B%22%E5%B1%8B%E9%A1%B6%E7%BA%BF%22%7D%0A%20%20K%20--%3E%20ROOF%0A%20%20ROOF%20--%3E%7C%E5%AD%97%E8%8A%82%2F%E5%B8%A6%E5%AE%BD%20%3E%20FLOPs%2F%E5%B3%B0%E5%80%BC%7C%20MEM%5B%22%E5%B8%A6%E5%AE%BD%E5%A2%99%EF%BC%9A%E5%8A%A0%E7%AE%97%E5%8A%9B%E6%97%A0%E7%94%A8%22%5D%0A%20%20ROOF%20--%3E%7Cbatch%20%E5%BE%88%E5%A4%A7%E3%80%81n%20%E4%BB%8D%E7%9F%AD%22%7C%20CMP%5B%22%E5%8F%AF%E8%83%BD%E9%9D%A0%E8%BF%91%E8%AE%A1%E7%AE%97%E5%B1%8B%E9%A1%B6%22%5D%0A%20%20MEM%20--%3E%20FIX%5B%22%E5%87%8F%E5%AD%97%E8%8A%82%20%2F%20%E5%8A%A0%E5%B8%A6%E5%AE%BD%20%2F%20%E5%8A%A0%20batch%20%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="批处理不能消灭" tabindex="-1">批处理不能消灭 \\(n\\) <a class="header-anchor" href="#批处理不能消灭" aria-label="Permalink to &quot;批处理不能消灭 $n$&quot;">​</a></h3><p>Batch 摊的是权重。每个请求自己的 KV 仍要各自搬，总 KV 流量随并发 \\(\\times\\) 平均 \\(n\\) 涨。高并发 + 长上下文是容量与带宽同时爆的象限。分页 KV 减少碎片，不减少渐近字节。前缀共享（同一系统提示）可以让多请求读同一段 KV，这是少数真正减 \\(K\\) 流量的调度手段，与算法压缩正交。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>屋顶线把核标成强度（FLOPs/字节）。Prefill 强度高，走计算顶；decode 强度低，走带宽顶。注意力在 \\(n\\) 极大时强度回升，但此前权重扫描已经把每步时间钉住，且 \\(n\\) 极大时容量墙往往先倒。因此「长上下文 decode 是注意力二次」只说对了累积 FLOPs，没说对逐步延迟的主导项——逐步延迟经常是线性扫 KV 的带宽。二次项在 prefill 和训练上更致命。</p><p>长链 RL 模型把分布推向更大的 \\(n\\)，等于主动走进墙里。测试时缩放加 \\(N\\) 或加树节点，是在并发维或节点维再乘流量。计算最优策略必须把带宽、而不是峰值 TFLOPS，当成稀缺资源。PRM 每步额外前向若也是瘦 GEMM，同样撞墙，不能假设验证器「很小所以免费」。</p><p><span class="marginnote">CUDA Graph 与 kernel fusion 减的是启动开销，对已经长达数十毫秒、被 HBM 主导的一步帮助有限。先减字节，再抠核。反过来，极短上下文、极小模型上，启动开销可以主导，那时 fusion 才是一阶。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="规划写清并发、长度、精度三元组" tabindex="-1">规划写清并发、长度、精度三元组 <a class="header-anchor" href="#规划写清并发、长度、精度三元组" aria-label="Permalink to &quot;规划写清并发、长度、精度三元组&quot;">​</a></h3><p>同一模型在 \\(n=512\\)、batch=1 与 \\(n=32\\mathrm{K}\\)、batch=8 上不是同一个瓶颈。SLA 应分 TTFT（prefill 计算顶）与 TPOT（decode 带宽顶）。把思考模式默认打开，等于把 \\(n\\) 的分布右移，必须单独做容量。端侧 DRAM 更窄，墙更早到来，公式相同，见<a href="/llm/on-device-kv">端侧 KV 预算</a>。</p><p>不要用 prefill 的 MFU 考核 decode 服务。不要把「H100 比 A100 算力高」直接外推成吐词倍数。量化 KV 会在长 \\(n\\) 后半段累积误差，针测与推理链要回归，不能只看短对话。分离式服务把 decode 池放到带宽型卡上是对症的，但 KV 从 prefill 池搬过来的时间要计入 TTFT，长前缀上可能得不偿失。投机解码、多 token 头同样是在用额外计算换更少的逐步扫权重；接受率一掉，每步又变回带宽墙，只是多付了草稿模型的流量。把这些技巧写进容量规划时，应同时给出接受率下限，而不是只给理想加速比。</p><p><span class="marginnote">屋顶线见 Williams et al., 2009。推理阶段划分见 Pope et al., 2023 与 DistServe（Zhong et al., 2024）。PagedAttention 见 Kwon et al., 2023。不要给「decode 显存墙」本身编造一篇独立 arXiv。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Decode 逐步查询长度为 1，工作点通常在带宽屋顶；加 FLOPS 不降 TPOT。</li><li>流量来自每步扫权重加扫 \\(O(n)\\) 的 KV；容量墙与带宽墙要分开治。</li><li>GQA/MLA/量化/驱逐减分子；HBM 规格与 batch 复用改分母或强度。</li><li>Batch 摊权重不摊各请求自己的 KV；长 \\(n\\) 高并发是最坏象限。</li><li>长思维链与测试时搜索是在主动增加 \\(n\\) 或并发，必须按带宽记账。</li><li>考核 decode 不要用 prefill MFU；TTFT 与 TPOT 分表。</li><li>出处：Williams et al., <em>Roofline</em>, CACM 2009；Pope et al., 2023；Kwon et al., vLLM, 2023；Zhong et al., DistServe, 2024。</li></ul>',13))])}const P=r(c,[["render",p]]);export{b as __pageData,P as default};
